<?php
require_once "db.php";requireUser();$id=filter_input(INPUT_GET,"slot_id",FILTER_VALIDATE_INT);if($_SERVER["REQUEST_METHOD"]==="POST")$id=filter_input(INPUT_POST,"slot_id",FILTER_VALIDATE_INT);if(!$id||$id<1)die("Invalid time slot.");$slots=new TimeSlotRepository($pdo);$slot=$slots->find($id);if(!$slot)die("Time slot not found.");$error="";
